package se.hemstyrning;

import android.app.*;
import android.content.*;
import android.content.pm.PackageManager;
import android.graphics.Color;
import android.net.Uri;
import android.net.nsd.*;
import android.os.*;
import android.view.*;
import android.webkit.*;
import android.widget.*;
import java.net.URI;

/** Restricted HTTPS web host. No JavascriptInterface and no Home Assistant credentials. */
public final class MainActivity extends Activity {
 private WebView web; private android.content.SharedPreferences prefs; private String origin=""; private boolean tv; private NsdManager nsd; private NsdManager.DiscoveryListener discovery;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);prefs=getSharedPreferences("hemstyrning",MODE_PRIVATE);tv=getPackageManager().hasSystemFeature(PackageManager.FEATURE_LEANBACK);getWindow().setFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON,WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);showSetup();}
 private int px(int n){return(int)(n*getResources().getDisplayMetrics().density);}
 private void showSetup(){if(web!=null){web.onPause();web.destroy();web=null;}LinearLayout form=new LinearLayout(this);form.setOrientation(1);form.setPadding(px(32),px(30),px(32),px(24));form.setBackgroundColor(Color.rgb(7,29,23));TextView title=new TextView(this);title.setText("Välkommen till Hemstyrning");title.setTextSize(28);title.setTextColor(Color.WHITE);form.addView(title);TextView note=new TextView(this);note.setText("Ange din HTTPS-server. Certifikatet måste vara betrott. Inloggning sker på servern. Långtryck Tillbaka för appinställningar.");note.setTextColor(Color.LTGRAY);form.addView(note);EditText server=new EditText(this);server.setSingleLine();server.setInputType(17);server.setText(prefs.getString("server",""));server.setHint("https://hemstyrning.example");form.addView(server);Spinner roles=new Spinner(this);String[] names={"Hem","3D-visning","Lista","Kontrollpanel","TV-visning","Senast använda vy"};roles.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,names));roles.setSelection(prefs.getInt("role",tv?4:0));form.addView(roles);Button connect=new Button(this);connect.setText("Anslut");form.addView(connect);TextView status=new TextView(this);status.setTextColor(Color.rgb(255,195,106));form.addView(status);Button search=new Button(this);search.setText("Sök server på lokala nätverket");form.addView(search);search.setOnClickListener(v->discover(server,status));connect.setOnClickListener(v->{try{URI u=new URI(server.getText().toString().trim());if(!"https".equals(u.getScheme())||u.getHost()==null||u.getUserInfo()!=null||u.getQuery()!=null||u.getFragment()!=null||(!u.getPath().isEmpty()&&!u.getPath().equals("/")))throw new Exception();origin="https://"+u.getRawAuthority();int role=roles.getSelectedItemPosition();prefs.edit().putString("server",origin).putInt("role",role).apply();String path=role==1?"/?view=3d":role==2?"/?view=list":role==3?"/control":role==4?"/?profile=tv":role==5?"/?native=last":"/?native=home";open(path);}catch(Exception e){status.setText("Ange en giltig HTTPS-server utan inloggningsuppgifter eller parametrar.");}});ScrollView scroll=new ScrollView(this);scroll.addView(form);scroll.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(scroll);server.requestFocus();}
 private void open(String path){web=new WebView(this);web.setBackgroundColor(Color.rgb(7,29,23));WebSettings settings=web.getSettings();settings.setJavaScriptEnabled(true);settings.setDomStorageEnabled(true);settings.setAllowFileAccess(false);settings.setAllowContentAccess(false);settings.setMixedContentMode(WebSettings.MIXED_CONTENT_NEVER_ALLOW);settings.setMediaPlaybackRequiresUserGesture(true);CookieManager.getInstance().setAcceptCookie(true);CookieManager.getInstance().setAcceptThirdPartyCookies(web,false);web.setWebChromeClient(new WebChromeClient());web.setWebViewClient(new WebViewClient(){@Override public boolean shouldOverrideUrlLoading(WebView view,WebResourceRequest request){Uri uri=request.getUrl();return !sameOrigin(uri);}@Override public void onPageFinished(WebView view,String url){CookieManager.getInstance().flush();Uri u=Uri.parse(url);if(sameOrigin(u)&&!u.getPath().startsWith("/auth")){String current=u.getPath()+(u.getQuery()==null?"":"?"+u.getQuery());prefs.edit().putString("last",current).apply();}}@Override public void onReceivedSslError(WebView view,SslErrorHandler handler,android.net.http.SslError error){handler.cancel();new AlertDialog.Builder(MainActivity.this).setTitle("Certifikatet är inte betrott").setMessage("Installera serverns betrodda CA eller använd ett giltigt TLS-certifikat. Valideringen kan inte kringgås.").setPositiveButton("Inställningar",(d,w)->showSetup()).show();}});web.setOnLongClickListener(v->false);web.setOnApplyWindowInsetsListener((v,i)->{v.setPadding(i.getSystemWindowInsetLeft(),i.getSystemWindowInsetTop(),i.getSystemWindowInsetRight(),i.getSystemWindowInsetBottom());return i;});setContentView(web);if(tv)getWindow().getDecorView().setSystemUiVisibility(5894);web.loadUrl(origin+path);web.requestFocus();}
 private boolean sameOrigin(Uri u){Uri base=Uri.parse(origin);return "https".equals(u.getScheme())&&base.getHost().equalsIgnoreCase(u.getHost())&&(base.getPort()<0?443:base.getPort())==(u.getPort()<0?443:u.getPort());}
 private void discover(EditText server,TextView status){if(discovery!=null)return;status.setText("Söker _hemstyrning._tcp…");nsd=(NsdManager)getSystemService(NSD_SERVICE);discovery=new NsdManager.DiscoveryListener(){public void onDiscoveryStarted(String s){}public void onDiscoveryStopped(String s){}public void onStartDiscoveryFailed(String s,int e){status.setText("Sökning kunde inte startas. Ange adress manuellt.");}public void onStopDiscoveryFailed(String s,int e){}public void onServiceLost(NsdServiceInfo s){}public void onServiceFound(NsdServiceInfo s){nsd.resolveService(s,new NsdManager.ResolveListener(){public void onResolveFailed(NsdServiceInfo s,int e){}public void onServiceResolved(NsdServiceInfo info){runOnUiThread(()->{String host=info.getAttributes().containsKey("hostname")?new String(info.getAttributes().get("hostname")):info.getHost().getHostAddress();server.setText("https://"+host+(info.getPort()==443?"":":"+info.getPort()));status.setText("Server hittad. Kontrollera namnet och certifikatet före anslutning.");});}});}};nsd.discoverServices("_hemstyrning._tcp.",NsdManager.PROTOCOL_DNS_SD,discovery);}
 @Override public boolean onKeyLongPress(int code,KeyEvent e){if(code==KeyEvent.KEYCODE_BACK){showSetup();return true;}return super.onKeyLongPress(code,e);}
 @Override public boolean onKeyDown(int code,KeyEvent e){if(code==KeyEvent.KEYCODE_MENU){showSetup();return true;}if(code==KeyEvent.KEYCODE_BACK){e.startTracking();return true;}return super.onKeyDown(code,e);}
 @Override public boolean onKeyUp(int code,KeyEvent e){if(code==KeyEvent.KEYCODE_BACK&&!e.isCanceled()){if(web!=null){web.evaluateJavascript("(function(){var b=document.getElementById('home-button');if(b&&!document.body.classList.contains('hem-start')){b.click();return true;}var e=new KeyboardEvent('keydown',{key:'Escape',bubbles:true,cancelable:true});return !document.dispatchEvent(e);})()",handled->{if(!"true".equals(handled)){if(web!=null&&web.canGoBack())web.goBack();else showSetup();}});}else showSetup();return true;}return super.onKeyUp(code,e);}
 @Override public void onPause(){super.onPause();CookieManager.getInstance().flush();if(web!=null)web.onPause();}
 @Override public void onResume(){super.onResume();if(web!=null)web.onResume();}
 @Override public void onDestroy(){if(discovery!=null)try{nsd.stopServiceDiscovery(discovery);}catch(Exception ignored){}if(web!=null)web.destroy();super.onDestroy();}
}
